package com.smartfinance.agent.investment.service;

import static org.assertj.core.api.Assertions.assertThat;
import com.smartfinance.agent.investment.marketdata.contract.MarketDataContract;
import org.junit.jupiter.api.Test;

class MarketDataContractTest {
    @Test void packagedJavaAndPythonDefinitionsProduceTheSameStorageIdentity() {
        // Golden values generated by Python contract_version for the same packaged configuration.
        assertThat(MarketDataContract.forProduct("PRICE","STOCK").version())
                .isEqualTo("250c9e378be7139e32226e4a579f8d05d6c90ad485b45b8f4885d00749ba709f");
        assertThat(MarketDataContract.forProduct("FINANCIALS","STOCK").version())
                .isEqualTo("3ca3b44edfa0af3e6f757b41d9699bea10febfd25a731fb7ac18fed13780aef4");
        assertThat(MarketDataContract.researchAdjustment("STOCK","NASDAQ")).isEqualTo("NONE");
        assertThat(MarketDataContract.researchAdjustment("STOCK","SSE")).isEqualTo("QFQ");
        assertThat(MarketDataContract.researchAdjustment("ETF","SSE")).isEqualTo("NONE");
    }
}
